package tenant

import (
	"embed"
	"io/fs"
	"net/http"
	"strconv"
)

// The portal's icons and web manifest, so a phone can add the portal to its home screen as an app.
// The images are generated by brand/generate.mjs (PATHS.portalIcons) and built into the binary, so
// deployments keep shipping the same three files in -ui-dir.
//
//go:embed portal-icons
var portalIcons embed.FS

const portalManifest = `{
  "name": "Super Cage",
  "short_name": "Super Cage",
  "lang": "zh-CN",
  "description": "登录 Super Cage 门户，打开服务器上的虚拟机工作台。",
  "start_url": "/",
  "scope": "/",
  "display": "standalone",
  "background_color": "#faf9f5",
  "theme_color": "#faf9f5",
  "icons": [
    { "src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any" },
    { "src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any" },
    { "src": "/icon-maskable-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable" }
  ]
}
`

var portalIconTypes = map[string]string{
	"/favicon.ico":           "image/x-icon",
	"/icon.svg":              "image/svg+xml",
	"/apple-touch-icon.png":  "image/png",
	"/icon-192.png":          "image/png",
	"/icon-512.png":          "image/png",
	"/icon-maskable-512.png": "image/png",
}

// servePortalIcon answers a GET or HEAD for one of the fixed icon paths or the manifest.
func servePortalIcon(w http.ResponseWriter, r *http.Request) bool {
	var body []byte
	contentType := ""
	if r.URL.Path == "/manifest.webmanifest" {
		body, contentType = []byte(portalManifest), "application/manifest+json"
	} else if kind, ok := portalIconTypes[r.URL.Path]; ok {
		data, err := fs.ReadFile(portalIcons, "portal-icons"+r.URL.Path)
		if err != nil {
			return false
		}
		body, contentType = data, kind
	} else {
		return false
	}
	w.Header().Set("Content-Type", contentType)
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	if r.Method == http.MethodGet {
		_, _ = w.Write(body)
	}
	return true
}
